insert into public.entries (ref, type, name, mark, grade, summary, entry, appears_in, reliability, cross_references_note, status) values
  ('SYNPTCL/LOC/001', 'LOC', 'Żerań (OP-Żerań, Z1)', 'PROX_SCAN', 'C', 'The hub of the survivor community, on the Vistula at the north of the corridor.', 'Power, radio and water access are routed from here. Class D ground. A hand-built radio stands here, with cable run up the stairwell toward the chimney. The houseboat where Diana lived is moored at Żerań.', null, null, null, null),
  ('SYNPTCL/LOC/002', 'LOC', 'Zoo (OP-Zoo, Z2)', 'PROX_SCAN', 'E', 'A community gathering place with large grounds and good cover.', 'About two hundred and ten people live in the Zoo, in enclosures made into houses. The lion house is the largest. The keeper''s house is also used. The Dendron reached the lower Zoo in the second flood.', null, null, null, null),
  ('SYNPTCL/LOC/003', 'LOC', 'Brodno (OP-Brodno, SZ)', 'PROX_SCAN', null, 'The old hospital, used by the survivors as their medical post.', 'Szpital Brodno. Medical, defensible, multiple buildings. Class D ground. Catalina Chmielewska treats patients with documented exposure here.', null, null, null, null),
  ('SYNPTCL/LOC/004', 'LOC', 'Praski (OP-P1)', 'PROX_SCAN', null, 'The market of the corridor, where trade and exchange take place.', 'Praga. Market, trade, exchange. Class D ground.', null, null, null, null),
  ('SYNPTCL/LOC/005', 'LOC', 'Rynek, Grochów (OP-R1)', 'PROX_SCAN', null, 'A gathering point in the middle of the corridor.', 'Class D ground. A diary entry is set in a room above the pharmacy.', null, null, null, null),
  ('SYNPTCL/LOC/006', 'LOC', 'Gocławek (OP-G1)', 'PROX_SCAN', null, 'The eastern edge of the corridor, exposed, and of high value for intelligence.', 'Class C ground.', null, null, null, null),
  ('SYNPTCL/LOC/007', 'LOC', 'Mała Afryka (OP-A1)', 'PROX_SCAN', null, 'A river access point on which the corridor depends for supply.', 'Class D ground.', null, null, null, null),
  ('SYNPTCL/LOC/008', 'LOC', 'Czerniaków (OP-C1)', 'PROX_SCAN', null, 'A river outpost in the south, with the escape route running out of it.', 'Diana Antonoff was last seen here on the night of the third flood. A crate with a label in a western language was pulled from the water here on 23 October.', null, null, null, null),
  ('SYNPTCL/LOC/009', 'LOC', 'Siekierki (OP-SK)', 'PROX_SCAN', null, 'An exposed industrial position on the southern riverside.', 'Class B ground.', null, null, null, null),
  ('SYNPTCL/LOC/010', 'LOC', 'Las (OP-L1)', 'PROX_SCAN', null, 'A concealed forest position that the Runners use as a waypoint.', 'Class D ground.', null, null, null, null),
  ('SYNPTCL/LOC/011', 'LOC', 'Przyloty (OP-P2)', 'PROX_SCAN', null, 'A position deep in the margin that can be reached only in some seasons.', 'Class B ground.', null, null, null, null),
  ('SYNPTCL/LOC/012', 'LOC', 'Pałac, Wilanów (OP-P3)', 'PROX_SCAN', null, 'The southernmost outpost, in large grounds, and a link in the escape route.', 'Not the Palace of Culture and Science.', null, null, null, null),
  ('SYNPTCL/LOC/013', 'LOC', 'Filtry (OP-F1)', 'PROX_SCAN', 'E', 'The water filtration station, the only reliably clean supply in the corridor.', 'The survivor position closest to the western ring. The supply is treated with charcoal and a three-stage sand bed. The post at R0 has it in sight.', null, null, null, null),
  ('SYNPTCL/LOC/014', 'LOC', 'Termika, the Docks (OP-Termika)', 'PROX_SCAN', null, 'The dock outpost where the water levels of the corridor are measured.', 'The engineer Lucasz keeps a table of water levels by day. It is the only reliable series in the corridor.', null, null, null, null),
  ('SYNPTCL/LOC/015', 'LOC', 'The Citadel', 'TRIGGER_V1', null, 'The occupier''s command centre, in the north of the city.', 'A nineteenth-century fortress on the Vistula. It controls river access from the north.', null, null, null, null),
  ('SYNPTCL/LOC/016', 'LOC', 'Palace of Culture and Science', 'TRIGGER_V1', null, 'A gift from Moscow, now a supply hub and the source of the broadcasts.', 'Designed to be seen from every part of the city. It carries a mast from which broadcasts are made in Russian and in Polish.', null, null, null, null),
  ('SYNPTCL/LOC/017', 'LOC', 'Old Town and Royal Castle', 'TRIGGER_V1', null, 'A rebuilt district, occupied for its symbolism.', 'Rebuilt after 1944 from photographs and paintings. Loudspeakers stand on the ramparts.', null, null, null, null),
  ('SYNPTCL/LOC/018', 'LOC', 'Saxon Garden and Łazienki', 'TRIGGER_V1', 'U', 'Open ground turned to air defence.', 'Missile batteries have been seen between the trees.', null, null, null, null),
  ('SYNPTCL/LOC/019', 'LOC', 'Szucha and Pawiak', 'TRIGGER_V1', 'U', 'Two buildings of interrogation and imprisonment that the occupier has taken over unchanged.', 'The German security police took Aleja Szucha 25 in 1939. The Russian force has reoccupied it. A tunnel is reported to the old prison at Pawiak.', null, null, null, null),
  ('SYNPTCL/LOC/020', 'LOC', 'R0 and RM', 'TRIGGER_V1', 'C', 'Two Russian posts on the water, one of which watches the filtration station.', 'R0 is the post that matters to the water. A rota is read aloud there every sixth day at 06:00 to six field commanders.', null, null, null, null),
  ('SYNPTCL/LOC/021', 'LOC', 'SP-1, Marymont', 'TRIGGER_V1', 'E', 'A screening point in the north, in a sports academy.', 'Two buses a day. They arrive with the blinds down and leave with the blinds up.', null, null, null, null),
  ('SYNPTCL/LOC/022', 'LOC', 'SP-2, Torwar', 'TRIGGER_V1', 'E', 'A screening point in an ice arena at the centre.', 'The lights are on all night. The ice is said to be still kept frozen.', null, null, null, null),
  ('SYNPTCL/LOC/023', 'LOC', 'SP-3, Służewiec', 'TRIGGER_V1', 'E', 'A screening point at the racecourse, the only one with its own fence.', 'Stables, a grandstand and a very large open ground. Persons queue on the open ground.', null, null, null, null),
  ('SYNPTCL/LOC/024', 'LOC', 'SP-4', 'TRIGGER_V1', 'U', 'A fourth screening point, known by its number only.', 'Known from a bus destination board seen on the embankment road.', null, null, null, null),
  ('SYNPTCL/LOC/025', 'LOC', 'Okęcie', 'TRIGGER_V1', 'U', 'The airport, a supply hub and the subject of a rumour.', 'Survivors believe certain persons are flown out from here. The word used is rendered. No source has seen it.', null, null, null, null),
  ('SYNPTCL/LOC/026', 'LOC', 'The shelters', 'TRIGGER_V1', 'U', 'Numbered places in the west where those screened are said to be sent.', 'Shelters 1 to 6 were heard of in 2034. The numbers rise.', null, null, null, null),
  ('SYNPTCL/LOC/027', 'LOC', 'Escape routes', 'ACT_SYNC', 'E', 'The gaps in the occupier''s ring through which survivors leave.', 'The western ring is not a wall. It is a series of eyes with gaps between them, and the gaps are the escape routes.', null, null, null, null),
  ('SYNPTCL/LOC/028', 'LOC', 'The sewers', 'ACT_SYNC', 'C', 'The tunnels under the city, used as a way through in 1944 and again now.', 'Anna carried Nikita down into the sewers, and the two travelled through them for three weeks. The Dendron has been found in the sewers of Targówek.', null, null, null, null),
  ('SYNPTCL/LOC/029', 'LOC', 'St Michael''s Cathedral', null, null, 'A flooded cathedral on the Praga shore.', 'A tide line runs across the nave pillars at the height of a hip. The roof is open in two places. Pigeons nest there.', null, null, null, null),
  ('SYNPTCL/LOC/030', 'LOC', 'The wetlands and the houseboat', null, null, 'The still water at the north of the corridor where Diana lived.', 'Diana lived alone on an abandoned houseboat moored at Żerań.', null, null, null, null),
  ('SYNPTCL/LOC/031', 'LOC', 'Żerań power station', null, 'C', 'A power station on which the Dendron does not grow.', 'The organism grows up to the edge of the old coal yard and stops.', null, null, null, null),
  ('SYNPTCL/CHR/001', 'CHR', 'Diana Antonoff', 'CHROMA_VAL', 'C', 'Ukrainian journalist, aged 28, who documented the survivor community and assembled the Protocols. Disappeared on the night of the third flood.', 'Diana Antonoff was a Ukrainian journalist who filed dispatches to Suspilne. She lived alone on an abandoned houseboat moored at Żerań, at the northern edge of the wetlands, where the others said the water ran quietest. She disappeared from the survivor outpost at Czerniaków on the night of the third flood, in the first January of the third year of the occupation. She was twenty-eight. Her last dispatch was filed the Tuesday before. No body was recovered and no statement was issued. The community she had documented entered her name among the missing and continued the work she had taught them. She is the source of the Codex marks and of the recorded testimonies. A nine-minute tape of her voice survives and is used once in the archive.', 'Protocol 001 (opening account); the Protocols collected under her name; Interlude I (tape)', 'C (3). Age, houseboat, disappearance and the missing-person entry are stated in the opening account and confirmed by later testimony. Her fiancé and the date of his death are in the project brief only and have not been confirmed in the manuscript (U).', null, 'Filed. Decide: the manuscript records her as disappeared, not dead; the entry follows it. Check the fiancé detail against the manuscript before release.'),
  ('SYNPTCL/CHR/002', 'CHR', 'Goya Liszka', 'CHROMA_VAL', 'C', 'Veteran of Mariupol and the Runners'' guide through the wetlands. Swears without pause. Hears drones before anyone else.', 'Goya Liszka served in the last cellar at Mariupol, under what had been a bakery. Ten men held it. Nine died when a shell came through. He was at the back of the room and lay three days among the dead because to move was to be heard. No camp or column would take him afterwards, because he does not sleep and watches the door. The Zone took him because it asked only what he could do. He can hear a drone in the air before anyone lifts a head, and he reads a man''s route from the mud on his boots. He knows where every Runner in the wetlands is at any hour, and which chimneys at Żerań still carry a watcher. He swears at everything: the boat, the sky, the dead, God, his own hands. The archivist records him as the most damaged person he met in the Zone and the most necessary. He speaks to children and drones in the same voice. In the clinic ward he called Pawel "the banker" and told him to count a Runner''s blood on the floor, and was told by Catalina that he was bleeding on her floor, which he was. He stood at the door when Lucasz was locked in the control room.', 'His own Protocol (Mariupol testimony); Protocol 001 (the table column headed Watch); Lucasz''s Protocol; Catalina''s clinic scene', 'C (3). Mariupol account is his own and is consistent across the passages read. His age of 42 is in the project brief only (U).', null, 'Filed. The older profile describes him as commander of field operations; the manuscript passages read show him as guide and watcher. Decide: kept to the manuscript.'),
  ('SYNPTCL/CHR/003', 'CHR', 'Felicyta "Fritha" Cielinski', 'CHROMA_VAL', 'C', 'Aged 19. Keeps photographs. Found in a church in Class D ground.', 'Fritha Cielinski was nineteen when the archivist met her. A Runner at the door, who would not come in, gave her name and said only that the girl in the church was not to be hurried. Her church stands in Class D ground, under the name of a place that was a cathedral. She keeps photographs. Forty-one prints came out of the water in her father''s jacket, which she found on a railing six days afterwards, caught by the sleeve. She dried them on a radiator in a stairwell without power. The emulsion had lifted and her mother''s face had slid a little to the left. Her account is that photographs do not keep people. They keep a version of the light that fell on someone, and a person who has made a photograph into a god has nothing else to pray to. She recalls being told she was nineteen and thinking it the most unfair thing anyone had said to her.', 'Her own Protocol; Protocol 001 (table entry for Class D)', 'C (2). The age and the forty-one prints are in her own account and the archivist''s description.', null, 'Filed. Decide: the church is linked to LOC/029 (St Michael''s Cathedral) on the strength of the Protocol 001 note; confirm at audit.'),
  ('SYNPTCL/CHR/004', 'CHR', 'Janek Dąbrowski', 'CHROMA_VAL', 'E', 'Wanderer. Lodged with Rosa and Marek. Spiritual anchor of the community.', 'Janek Dąbrowski came to rest in September, when Rosa Olszewska offered him the empty back room of the third-floor flat in Białołęka that she shared with Marek. The room had a window, a bed with a real mattress, a wool blanket and a stove, and had been empty since the winter. His account of the offer is that it is not a sin to want to be kept, and that the rule, if there is one, is not that a person must not want but that a person must not want what belongs to someone else and call it theirs. The room was Rosa''s to give, not to keep.', 'His own Protocol; Marek''s Thursday stories (recorded in the archivist''s note)', 'E (1). Drawn from his own testimony. His age and earlier life are not given in the passages read.', null, 'Filed in short form. Decide: the older profile gives details not found in the manuscript passages read; they are left out until confirmed.'),
  ('SYNPTCL/CHR/005', 'CHR', 'Lucasz Kowalski', 'CHROMA_VAL', 'C', 'Engineer who runs the control room. Locked in it for seven hours by his friends.', 'Lucasz Kowalski is the engineer of the community''s systems. He reads the gauge at the dock and keeps the control room. Artur diagnosed that the engineer had a fault and that only one person could fix it. On a Thursday in late October a group arranged for Lucasz to be locked in the control room: Artur took the key from his belt, Goya stood at the door with folded arms and told him to sit down, and Diana neither took part nor stopped it. The door did not open for seven hours. On the night of the pressure fall his reading of the dock gauge at 18:00, up fourteen centimetres on the morning, was relayed to the archivist by Artur, who ran.', 'His own Protocol; the flood-night field record', 'C (2). His own account and the field record agree.', null, 'Filed. The location of the control room is not given in the passages read, so no LOC reference is entered.'),
  ('SYNPTCL/CHR/006', 'CHR', 'Tanja Dopolewka', 'CHROMA_VAL', 'C', 'Aged 36. Violinist who teaches a mixed class of survivors.', 'Tanja Dopolewka was thirty-six, small and square-shouldered, in a man''s cardigan. By every account the archivist was given she had been one of the best violinists in Warsaw. She ran a room on the second floor with a piano, a carpet and a row of small plastic chairs. On the Saturday of the visit eight people were present, aged between nine and seventy, each holding an instrument. She taught with the words "Again" and "Listen to her, not to yourself". When a boy of eleven dropped his bow, a black carbon-fibre bow with white hair, she went still for about three seconds, as a person does who hears their name spoken in another room, then returned it to his hand and said "Again".', 'Her own Protocol', 'C (2). Observed directly by the archivist and consistent with the testimony.', null, 'Filed. The location of the room is not given in the passage read. The meaning of the bow is left to her Protocol.'),
  ('SYNPTCL/CHR/007', 'CHR', 'Catalina Chmielewska', 'CHROMA_VAL', 'C', 'Medic who runs the clinic. Aged 40 at first account, 41 later.', 'Before the war Catalina Chmielewska was a software engineer in Warsaw, at a firm that made scheduling systems for hospitals. After the invasion she trained as a volunteer medic. She came to the Zone from Kraków eighteen months before the archivist met her. She ran a clinic from a former bank, using the vault for stores. People called her selfless. Her rule for the dispensary was strict allocation by list. On one occasion there were forty courses of an antibiotic, allocated to the children, the post-operative and a man who had been shot. A Mrs Lewandowska, aged forty-six, with pneumonia in the Zoo, was not on the list. Her fourteen-year-old daughter, who had been stealing food from half the district to keep her alive, came to the clinic door at night and stood without knocking. Catalina did not let her in.', 'Her own Protocol; the clinic scene in Pawel''s Protocol', 'C (3). Her own testimony and the archivist''s note. The age given is 40 in the archivist''s note and 41 in her later testimony.', null, 'Filed. A secret relationship is part of her planned arc and is in the project brief; it has not been confirmed in the passages read (U). Outcome for Mrs Lewandowska not confirmed in the passages read.'),
  ('SYNPTCL/CHR/008', 'CHR', 'Magda Wiśniewska', 'CHROMA_VAL', 'E', 'The Listener. Transcribed the Palace loudspeaker.', 'Magda Wiśniewska listens. She made the written transcript of the Palace loudspeaker broadcasts, morning and evening, and the archivist used her words unaltered. The four-second pause in the broadcast is on her page. Her transcript is the only record of the voice that a resident of Block C, Wiktor Szeliga, heard twice a day.', 'Interlude I (as source); her own Protocol', 'E (1). Only her role as transcriber is confirmed in the passages read.', null, 'Short entry. Her own Protocol has not yet been read for this entry. Decide: expanded in the audit pass.'),
  ('SYNPTCL/CHR/009', 'CHR', 'Zoysa Zieliński', 'CHROMA_VAL', 'C', 'Aged 17 at the first account and 19 later. Captain and flying instructor at the Dęblin air academy.', 'Zoysa was seventeen when she stood in the corner of Marek''s kitchen on a Thursday, boots tucked under her, back against the wall, with the bearing of a girl taught to stand to attention before she could read. When the story ended she stood, said "Thank you, Pan Marek", and left without her coat. Later, aged nineteen, she received the archivist at the air academy at Dęblin, precisely at ten to the hour, in an office with a map on one wall. She was reported to be the youngest officer of her rank in the Polish army, and wore the rank as a thing issued rather than chosen. The academy had four hundred and six students, aged fourteen to thirty-one, eleven aircraft that fly and nineteen that do not. They keep the nineteen because they teach more. During one period she was absent two nights; Goya said she was on patrol, but the roster showed no entry.', 'Marek''s Thursday story; her own Protocol', 'C (2). Two accounts, taken at different times.', null, 'Filed. The older profile gives her age as 17 only and describes her as male in one place. The manuscript gives both ages and a female captain. Decide: the manuscript is followed.'),
  ('SYNPTCL/CHR/010', 'CHR', 'Alisia Lewandowska', 'CHROMA_VAL', 'E', 'Thief. Aged 14 when she stole to keep her mother alive, 16 when the archivist met her.', 'Alisia Lewandowska was fourteen when she stole food from half the district to keep her mother alive. The mother, Mrs Lewandowska, was forty-six and had pneumonia in the Zoo. When the archivist met Alisia she was sixteen, thin and watchful, in a boy''s anorak, and she asked whether the archivist wanted tea before deciding whether he was welcome. He said he did. She said "Good answer" and let him in. A girl of about fourteen in a too-large grey anorak was seen entering the keeper''s house at the Zoo by a side window with no catch. She took half a loaf, a bag of flour and a grey blanket in eleven seconds. The archivist watched and did not intervene.', 'Her own Protocol; Catalina''s Protocol; the archivist''s keeper''s-house note', 'E (2). The identity of the keeper''s-house thief with Alisia is by inference and the passage does not name her.', null, 'Filed. Decide: the manuscript gives two ages because the accounts were taken at different times; both are kept.'),
  ('SYNPTCL/CHR/011', 'CHR', 'Anna', 'TORUS_VAL', 'E', 'Elder of the two children at the keeper''s house, aged about 13.', 'Anna is perhaps thirteen. She and Nikita live in the keeper''s house at the south end of the Zoo, in the old reptile garden, a small brick house with a pitched roof and a tin chimney, now belonging to Pan and Pani Wróbel, who took in both children. The archivist visited her with a message from Catalina. Her home was robbed of bread, flour and a blanket while he watched.', 'The archivist''s keeper''s-house note; Nikita''s Protocol', 'E (1). The surname Kowalczyk in the older profile is not found in the passages read (U).', null, 'Filed. Her part in the sewers is left to be confirmed.'),
  ('SYNPTCL/CHR/012', 'CHR', 'Nikita Sokołowski', 'TORUS_VAL', 'C', 'Aged 6. Does not speak. Hears what instruments do not.', 'Nikita is six and does not speak. She is frightened of a single knock, so visitors knock twice and wait. She and the archivist built a language eleven items long, which is the only record of their exchanges. She has been hearing, throughout, what the instruments pick up and the adults do not. The archivist filed her drawing under MAG_REF_400, the mark for the organism itself, and copied it in his own hand. It is the first time he took a symbol from a child.', 'Her own Protocol; the keeper''s-house note', 'C (2). The archivist''s direct observation and her drawing.', null, 'Filed. Decide: surname spelled as in the project brief. The feminine form Sokołowska would be usual in Polish; flagged for the author.'),
  ('SYNPTCL/CHR/013', 'CHR', 'Artur Wójcik', 'TORUS_VAL', 'E', 'Boy of about 12 who builds radios and drones.', 'At Żerań the archivist found a hand-built radio assembled from boards, scavenged parts and hand-wound coils, mounted in a gutted instrument case, and a boy of about twelve working on its inside with a tool he had made himself. Artur reads what makes a machine stall. In his account the engineer Lucasz had a fault that only one person could fix. He took the key from Lucasz''s belt for the lock-in, and on the pressure-fall night he ran the dock gauge reading to the archivist.', 'Protocol 001 (arrival at OP-Żerań); Lucasz''s Protocol; the flood-night field record', 'E (2). The boy at the radio is not named in the arrival passage; the identification rests on the role. The brief gives his age as 11.', null, 'Filed. Decide: age kept as "about 12" to match the manuscript.'),
  ('SYNPTCL/CHR/014', 'CHR', 'Pawel', 'TORUS_VAL', 'C', 'Former banker, aged 35. Keeps the stores. Will not carry a weapon.', 'Pawel was a banker, thirty-five. He was in Warsaw because his father was in a nursing home in Praga and could not be moved, and when the water came he would not leave him. He stayed until the old man died, then stayed because he did not know where else to go. He keeps the stores and counts. He will not carry a weapon and that is the whole of his reputation. Men who had been at Mariupol called him a coward. The archivist did not, and records a man who has decided at some cost what he will not do. In the clinic ward Goya told him to count the blood on the floor, and he did. His ears went red and his pencil stopped, then began again.', 'His own Protocol; Catalina''s clinic scene', 'C (2). His account and the archivist''s observation.', null, 'Filed. No surname given in the passages read.'),
  ('SYNPTCL/CHR/015', 'CHR', 'Marek Olszewski', 'TORUS_VAL', 'C', 'Elder of the community. Tells stories on Thursdays.', 'Marek and Rosa are the two old people of the Zone, who passed through earlier wars as children and as parents. They keep a third-floor flat in Białołęka that stayed above the water. On Thursdays Marek tells stories at the kitchen table to whoever comes, Rosa makes tea and the children sit under the table, which is the warm place. The archivist counted eleven present at one telling and chose not to record it, because some things are for being in the room.', 'The archivist''s Thursday note; Janek''s Protocol; Zoysa''s account', 'C (3). Three separate passages.', null, 'Filed. The 1944 captain story, told in the sewers context, is not summarised here because the archivist declined to record it; confirm whether the manuscript carries it elsewhere.'),
  ('SYNPTCL/CHR/016', 'CHR', 'Rosa Olszewska', 'TORUS_VAL', 'C', 'Elder who gave Janek a room.', 'Rosa shares the third-floor flat in Białołęka with Marek. In September she offered Janek the empty back room, saying it had been empty since the winter. She makes tea at Marek''s Thursday tellings.', 'Janek''s Protocol; the archivist''s Thursday note', 'C (2).', null, 'Filed.'),
  ('SYNPTCL/CHR/017', 'CHR', 'The Runners', 'TORUS_VAL', 'C', 'Child couriers. Also called the Ducks.', 'The Runners are children who carry messages when the Russians jam the air, going where a boat would be seen and a man would be shot. Goya says they are called the Ducks, "whatever they''re calling them this year". They keep waypoints in the forest and use a winter route recorded in the Protocol 001 tables. A Runner of about thirteen was brought to the clinic with a bullet through the forearm and behaved as if it were a bee sting. Goya knows where each Runner in the wetlands is at any hour.', 'Protocol 001; Goya''s Protocol; the clinic scene', 'C (3).', null, 'Filed. The origin of the name Ducks is not given in the passages read.'),
  ('SYNPTCL/CHR/018', 'CHR', 'Alex, the archivist', 'TORUS_VAL', 'C', 'Journalist who assembled the Protocols after the war.', 'Alex is the narrator of the archive. He travelled to the Zone to collect the testimonies and diaries, assessed each testimony for reliability, and compiled them into the Protocols. Where he writes a reconstruction he puts it in italics and brackets, names the source of each passage, and says what he supplied himself. He did not intervene when he watched a child steal from the keeper''s house, and records that failure. He has chosen not to record Marek''s Thursday tellings.', 'Throughout', 'C (3). Self-description in the archive. The surname Kovalchuk comes from the older profile and is not found in the passages read (U).', null, 'Filed. Decide: surname left out of the entry.'),
  ('SYNPTCL/CHR/019', 'CHR', 'Wiktor Szeliga', 'TORUS_VAL', 'E', 'Resident of Block C. Left no testimony.', 'Wiktor Szeliga gave no testimony and kept no diary. His traces are a pencil ration ledger kept by the block warden, Magda Wiśniewska''s transcript of the Palace loudspeaker, nine minutes of Diana''s tape and a neighbour''s account given in Lublin after the war. On the fifteenth he crossed the Vistula. The ledger records one adult male, ambulant, and one female child, nine, ambulant. A line for a non-ambulant person is ruled through, with no entry beside it. The neighbour said someone had gone up on the Thursday, that it was very quiet, that the room had been tidied and the bed made. He is a man who counts stairs.', 'Interlude I', 'E (4). Four sources, none his own; the archivist states that it is a reconstruction.', null, 'Filed. Interior passages are the archivist''s and are marked as such in the manuscript.'),
  ('SYNPTCL/CHR/020', 'CHR', 'Sasha Lebedev', 'GRID_FAIL', 'E', 'Russian operator at Observation Post R0. Relieved on 11 October.', 'Sasha Lebedev left no account. The archive holds eleven photocopied rota sheets, the post log in a green hardback notebook with a red spine, forty-four text messages from his mother recovered from a handset left in a drawer, a chocolate-bar wrapper and a receipt. On R0 he reads the sixth-day rota aloud to six field commanders, who answer "Received" and a number. He says "B" in place of the name of the authorising officer and keeps the same voice at the same speed throughout. He was relieved on 11 October. The log passes to a blocky, heavy hand. On the first page of that hand is the old instruction, "Do not add anything. Do not leave anything out. Do not pause", and under it in pencil, in another hand, "He paused."', 'Interlude II', 'E (4). Reconstruction from documents; interviews with men who did the same work are used with stated caution.', null, 'Filed.'),
  ('SYNPTCL/CHR/021', 'CHR', 'Colonel Viktor Nikolaevich Sorokin', 'GRID_FAIL', 'E', 'Commanding officer of the occupying force. Based at the Citadel.', 'Aged approximately 55 (E). His record, as far as it is known, is that of a professional: no excesses are attributed to him or to his staff in his name. He does not appear to hate the city. He appears to have orders and the competence to carry them out. It is reported that he reads. A source who delivered food to his office in July saw a clear desk with a single paperback and a glass of water. The title was not seen.', 'Protocol 002, section 7.1', 'E (2). Reported by sources who did not meet him.', null, 'Filed. Decide: the older profile name "Viktor" is taken as this officer.'),
  ('SYNPTCL/CHR/022', 'CHR', 'Major Budanov', 'GRID_FAIL', 'E', 'Staff officer whose office issues the rota. Referred to as "B".', 'Major Budanov''s office issues the sixth-day rota at 06:00. It lists the day''s movements by block, time, crew, task, duration, authorising officer and status. Each task is authorised "B". Operators read the order without saying the name.', 'Interlude II', 'E (1). Known only through the rota.', null, 'Filed in short form.'),
  ('SYNPTCL/CHR/023', 'CHR', 'Captain Isaev', 'GRID_FAIL', 'E', 'Officer of the day at the Poniatowski Bridge checkpoint, aged 31.', 'Captain Isaev is thirty-one and sweats a little. He reports to the staff officer at 08:40. He declines tea once, then accepts it. On the night in question there were 212 crossings. Of these, 190 were assessed on the bridge at Stage 2 or 3 and passed to the reception hall on the left bank. Twenty-two did not pass. He was asked what became of them and told the officer.', 'An Interlude narrated by an unnamed Russian staff officer', 'E (1).', 'None entered. The Poniatowski Bridge has no location entry.', 'Filed. Decide: the chapter number of the Interlude is to be confirmed at audit.'),
  ('SYNPTCL/CHR/024', 'CHR', 'Mrs Lewandowska', 'TORUS_VAL', 'E', 'Alisia''s mother, aged 46, ill with pneumonia in the Zoo.', 'Mrs Lewandowska had pneumonia and was not on Catalina''s antibiotic list. Her daughter stole food from half the district to keep her alive.', 'Catalina''s Protocol', 'E (1).', null, 'Filed. Outcome not confirmed in the passages read.'),
  ('SYNPTCL/CHR/025', 'CHR', 'Pan and Pani Wróbel', 'TORUS_VAL', 'E', 'Elderly couple who took in Anna and Nikita.', 'Pan and Pani Wróbel are an elderly couple who live in the keeper''s house at the south end of the Zoo and have taken in two children, Anna and Nikita.', 'The archivist''s keeper''s-house note', 'E (1).', null, 'Filed.'),
  ('SYNPTCL/OBJ/001', 'OBJ', 'Dendron', 'MAG_REF_400', 'C', 'An ancient organism from the Siberian permafrost, weaponised.', 'Vine-like, it spreads through the floodwater, absorbs water and clogs sewers. It emits chemicals that induce apathy and compliance.', null, null, null, null),
  ('SYNPTCL/OBJ/002', 'OBJ', 'Dendron Dust', 'SHIFT_REF_04', 'E', 'A psychedelic scraped from the surface of the Dendron.', 'Used by members of the resistance in rituals.', null, null, null, null),
  ('SYNPTCL/OBJ/003', 'OBJ', 'The Protocols (Diana''s bequest)', 'FLUX_SYNC', 'C', 'The collected papers and recordings Diana left, from which the archive is assembled.', 'Three binders, a box of cassette tapes and some memory cards, a canvas roll of photographs, and a manila folder with Alex''s name on it in her handwriting. Binder two holds Annex A, a list of forty-one streets with both names.', null, null, null, null),
  ('SYNPTCL/OBJ/004', 'OBJ', 'Appendix: The Brief', 'FLUX_SYNC', 'C', 'The document that names the programme behind the Dendron.', 'Records Operation Neural Harvest, its origins, the parties that supplied the organism and the science, and its aim: population compliance optimisation.', null, null, null, null),
  ('SYNPTCL/OBJ/005', 'OBJ', 'Janek''s prayer book', 'FLUX_SYNC', 'C', 'Taped prayer book, one of Janek''s three possessions.', 'The spine has been taped many times, and the older layers show yellow under the new. He let the archivist hold it for about a minute.', null, null, null, null),
  ('SYNPTCL/OBJ/006', 'OBJ', 'Fritha''s prints', 'FLUX_SYNC', 'C', 'Forty-one family photographs recovered from the flood.', 'Carried in her father''s jacket, found on a railing six days after the flood and dried on a radiator. The emulsion had lifted and her mother''s face had shifted a little to the left.', null, null, null, null),
  ('SYNPTCL/LOR/001', 'LOR', 'Operation Neural Harvest', 'LOAD_STRESS', 'C', 'The programme behind the Dendron, named in the Brief.', 'Described in Protocol 005 and the appendix. Its stated aim is population compliance optimisation.', null, null, null, null),
  ('SYNPTCL/LOR/002', 'LOR', 'The stages of compliance', 'LOAD_STRESS', 'E', 'The occupiers'' scale for assessing how far a person has been pacified.', 'Stage 3 is the point at which a person will give up a name when asked. Stage 4 is the point at which they will give up one without being asked. The district dashboard showed 71.2 per cent assessed at Stage 3 or above.', null, null, null, null),
  ('SYNPTCL/LOR/003', 'LOR', 'The Warsaw Uprising of 1944', 'DIFF_REF_89', 'C', 'The historical parallel the survivors and the archivist draw on.', 'The Home Army fought for sixty-three days. The Red Army stood on the east bank and did not cross. Eighty-five per cent of the left bank was destroyed.', null, null, null, null),
  ('SYNPTCL/LOR/004', 'LOR', 'Street names', 'PORE_SEQ', 'C', 'Survivors navigate by street names withdrawn before 1944.', 'Forty-one streets are listed with both names in Annex A, held in binder two.', null, null, null, null),
  ('SYNPTCL/LOR/005', 'LOR', 'Rising water', 'DIFF_REF_89', 'E', 'Why the flood does not recede.', 'Reservoirs are damaged, the dam at Włocławek is non-functional, breached dikes cannot be repaired under occupation, and pumping stations have no power.', null, null, null, null);
